import{_ as i,o as t,c as r,at as a}from"./chunks/framework.CY22Hent.js";const p=JSON.parse('{"title":"软件设计师笔记_科目一_精简考点","description":"","frontmatter":{"title":"软件设计师笔记_科目一_精简考点","date":"2025-05-22T00:00:00.000Z","lastUpdated":"2025-11-07T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记_科目一_精简考点.md","filePath":"blogs/软考/软件设计师笔记_科目一_精简考点.md"}'),o={name:"blogs/软考/软件设计师笔记_科目一_精简考点.md"};function e(n,l,s,d,u,h){return t(),r("div",null,[...l[0]||(l[0]=[a('<p>[toc]</p><h1 id="软件设计师笔记-科目一-精简考点" tabindex="-1">软件设计师笔记_科目一_精简考点 <a class="header-anchor" href="#软件设计师笔记-科目一-精简考点" aria-label="Permalink to &quot;软件设计师笔记_科目一_精简考点&quot;">​</a></h1><p>科目一：综合知识（选择题）。满分75分，需要达到45分才能合格。</p><blockquote><p>科目一知识点分布</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>分数</th><th>说明</th><th>比例</th></tr></thead><tbody><tr><td>第 5 章 软件工程基础知识</td><td>13</td><td>开发模型、设计原则、测试方法、质量特性、CMM、Pert图、风险管理</td><td>17.33%</td></tr><tr><td>第 7 章 面向对象</td><td>11</td><td>面向对象基本概念、面向对象分析与设计、UML、设计模式</td><td>14.67%</td></tr><tr><td>第3章 数据结构 和 第8章 算法设计</td><td>9</td><td>数组、栈、队列、树与二叉树、图、查找与排序、常见算法</td><td>12%</td></tr><tr><td>第 2 章 程序设计语言</td><td>6</td><td>文法、有限自动机、正规式、语句的作用、语句的语义、程序的控制结构、函数调用的参数传递、各种程序语言的特点比较</td><td>8%</td></tr><tr><td>第 1 章 计算机硬件基础</td><td>6</td><td>浮点数运算、溢出、算术、逻辑运算、计算机体系结构分类、指令系统基础、CISC与RISC、流水线、Cache存储器可靠性分析、校验方法</td><td>8%</td></tr><tr><td>第 4 章 操作系统</td><td>6</td><td>进程状态转换图、信号量与PV操作、死锁问题、银行家算法、段页式存储、页面置换算法、磁盘调度、树形文件系统</td><td>8%</td></tr><tr><td>第 9 章 数据库系统</td><td>6</td><td>E-R模型、关系代数、元组演算、规范化理论（键、范式、模式分解）、并发控制</td><td>8%</td></tr><tr><td>第 10 章 计算机网络</td><td>5</td><td>OSI模型、TCP/IP协议族、子网划分、常用的网络命令</td><td>6.6%</td></tr><tr><td>第 10 章 信息安全知识</td><td>5</td><td>加密解密技术、网络安全、计算机病毒</td><td>6.6%</td></tr><tr><td>第 11 章 知识产业与标准化</td><td>3</td><td>作品保护时间、侵权判定、知识产权归属、标准的分类、标准代号</td><td>4%</td></tr><tr><td>专业英语</td><td>5</td><td>专业英语填空</td><td>6.6%</td></tr></tbody></table><h2 id="一、软件工程基础知识-13分-【最高优先级】" tabindex="-1">一、软件工程基础知识（13分）【最高优先级】 <a class="header-anchor" href="#一、软件工程基础知识-13分-【最高优先级】" aria-label="Permalink to &quot;一、软件工程基础知识（13分）【最高优先级】&quot;">​</a></h2><h3 id="高频考点-按考试频率排序" tabindex="-1">高频考点（按考试频率排序） <a class="header-anchor" href="#高频考点-按考试频率排序" aria-label="Permalink to &quot;高频考点（按考试频率排序）&quot;">​</a></h3><ol><li><p><strong>开发模型</strong>（必考，2-3分）</p><ul><li>瀑布、原型、螺旋、敏捷模型特点与适用场景</li><li>敏捷开发：Scrum、XP核心概念</li><li>增量模型、迭代模型的区别与应用场景（易与敏捷开发混淆）</li><li>V 模型（测试与开发阶段对应关系，近年考频上升）</li></ul></li><li><p><strong>软件测试</strong>（必考，2-3分）</p><ul><li>测试阶段：单元→集成→系统→验收</li><li>测试方法：黑盒（等价类、边界值）、白盒（语句/路径覆盖）</li><li>集成测试策略：自顶向下（需桩模块）、自底向上（需驱动模块）</li><li>测试用例设计原则（边界值必取极值、等价类划分需覆盖有效 / 无效类）</li><li>回归测试、冒烟测试的定义与应用场景</li></ul></li><li><p><strong>软件质量特性</strong>（GB/T 16260）（必考）</p><ul><li>六大特性：功能性、可靠性、易用性、效率、维护性、可移植性</li><li>各特性的子特性（如可靠性包含成熟性、容错性、易恢复性；功能性包含适合性、准确性等）</li><li>ISO 9126 与 GB/T 16260 的对应关系（偶尔考）</li></ul></li><li><p><strong>CMM/CMMI</strong>（常考）</p><ul><li>五个等级：初始级→可重复级→已定义级→已管理级→优化级</li><li>CMMI 两种表示法：阶段式（对应 CMM）、连续式（按过程域能力分级）</li><li>各等级核心特征（如可重复级聚焦项目级流程复用，已定义级聚焦组织级标准流程）</li></ul></li><li><p><strong>风险管理</strong>（1分）</p><ul><li>风险识别→分析→应对→监控</li><li>风险类型：技术风险、管理风险、商业风险（举例判断）</li><li>风险应对策略：规避、转移、缓解、接受（区分应用场景）</li></ul></li><li><p><strong>Pert 图 / 甘特图</strong>（1-2 分）：</p><ul><li>Pert 图关键路径计算（总工期、松弛时间）</li><li>甘特图与 Pert 图的适用场景对比</li></ul></li><li><p><strong>软件配置管理</strong>（1 分）：</p><ul><li>基线（需求基线、设计基线）、版本控制（SVN/Git 核心概念）</li></ul></li></ol><hr><h2 id="二、面向对象-11分-【高优先级】" tabindex="-1">二、面向对象（11分）【高优先级】 <a class="header-anchor" href="#二、面向对象-11分-【高优先级】" aria-label="Permalink to &quot;二、面向对象（11分）【高优先级】&quot;">​</a></h2><h3 id="高频考点" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>UML图</strong>（必考，3-4分）</p><ul><li>用例图：参与者、包含/扩展关系</li><li>类图：关联/聚合/组合/继承关系</li><li>时序图：消息顺序、对象生命线</li><li>其他常考 UML 图：活动图（流程分支、泳道）、状态图（对象状态转换）、部署图（硬件 + 软件映射）</li><li>包含 vs 扩展关系核心区别：包含是必选、扩展是可选且有触发条件</li><li>组合 vs 聚合：组合是 “整体消亡部分消亡”（如人与心脏），聚合是 “整体消亡部分可独立”（如人与手机）</li></ul></li><li><p><strong>设计模式</strong>（必考，2-3分）</p><ul><li>创建型：单例、工厂、抽象工厂</li><li>结构型：适配器、装饰器、代理</li><li>行为型：观察者、策略、模板方法</li><li>单例模式：饿汉式 / 懒汉式实现区别（线程安全问题）</li><li>装饰器 vs 适配器：装饰器 “增强功能”，适配器 “转换接口”</li><li>新增常考模式：中介者模式、迭代器模式（近年偶考）</li><li>设计模式核心原则：针对接口编程，而非针对实现编程</li></ul></li><li><p><strong>面向对象概念</strong>（1-2分）</p><ul><li>封装、继承、多态</li><li>接口与抽象类区别</li><li>多态分类：编译时多态（重载）、运行时多态（重写）</li><li>接口与抽象类的语法区别（Java 为例：接口多实现、抽象类单继承；接口方法默认 public abstract，抽象类可含普通方法）</li><li>泛型、委托、组合等概念（近年新增考点）</li></ul></li></ol><hr><h2 id="三、数据结构与算法-9分-【中高优先级】" tabindex="-1">三、数据结构与算法（9分）【中高优先级】 <a class="header-anchor" href="#三、数据结构与算法-9分-【中高优先级】" aria-label="Permalink to &quot;三、数据结构与算法（9分）【中高优先级】&quot;">​</a></h2><h3 id="高频考点-1" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-1" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>树与二叉树</strong>（必考，3-4分）</p><ul><li>二叉树性质、遍历方式（前/中/后序）</li><li>特殊二叉树：满二叉树、完全二叉树、BST</li><li>二叉树遍历的非递归实现（栈的应用，偶尔考代码片段判断）</li><li>平衡二叉树（AVL）：平衡因子、旋转规则（左左 / 右右 / 左右 / 右左）</li><li>哈夫曼树：构造方法、带权路径长度计算（必考 1 分）</li><li>B 树 / B + 树：核心特征（数据库索引应用，近年考频上升）</li></ul></li><li><p><strong>排序算法</strong>（必考，2分）</p><ul><li>时间复杂度：O(n²)（冒泡）、O(nlogn)（快排、归并、堆排）</li><li>稳定性判断</li><li>各排序算法的适用场景（如快排不适用于近乎有序数组，堆排适用于 TopK 问题）</li><li>基数排序、希尔排序的时间复杂度与稳定性</li><li>排序算法的空间复杂度（快排 O (logn)、归并 O (n)）</li></ul></li><li><p><strong>图</strong>（2-3分）</p><ul><li>存储：邻接矩阵、邻接表</li><li>遍历：DFS、BFS</li><li>拓扑排序（必考）、最短路径</li><li>最短路径算法：Dijkstra（单源、无负权）、Floyd（多源）</li><li>最小生成树：Prim（稠密图）、Kruskal（稀疏图）</li><li>强连通分量、关键路径（与 Pert 图结合考）</li></ul></li><li><p><strong>线性结构</strong>（2分）</p><ul><li>栈（表达式求值）、队列（循环队列）、链表</li><li>循环队列的判空 / 判满条件（两种实现方式：牺牲一个位置、标记位）</li><li>链表：双向链表、循环链表的操作（插入 / 删除节点）</li><li>哈希表：哈希函数、冲突解决方法（开放定址法、链地址法，必考 1 分）</li></ul></li><li><p><strong>查找算法</strong></p><ul><li>顺序查找、二分查找（时间复杂度、适用场景）</li></ul></li><li><p><strong>算法复杂度分析</strong></p><ul><li>最好 / 最坏 / 平均时间复杂度，空间复杂度（含辅助空间）</li></ul></li></ol><hr><h2 id="四、操作系统-6分-【中优先级】" tabindex="-1">四、操作系统（6分）【中优先级】 <a class="header-anchor" href="#四、操作系统-6分-【中优先级】" aria-label="Permalink to &quot;四、操作系统（6分）【中优先级】&quot;">​</a></h2><h3 id="高频考点-2" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-2" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>进程管理</strong>（必考，2-3分）</p><ul><li>进程三态转换：就绪→运行→阻塞</li><li>五态模型（新增创建态、终止态，近年考）</li><li>PV操作与信号量：进程同步与互斥实现</li><li>PV 操作经典例题：生产者 - 消费者、读者 - 写者、哲学家进餐问题（需掌握信号量设置与操作流程）</li><li>线程与进程的区别（资源分配、调度、开销）</li></ul></li><li><p><strong>死锁</strong>（必考，2分）</p><ul><li>四个必要条件、银行家算法</li><li>死锁预防（破坏必要条件）、避免（银行家算法）、检测与解除（资源分配图）</li><li>银行家算法计算：安全性检查、最大需求 / 分配 / 剩余资源的关系</li></ul></li><li><p><strong>存储管理</strong>（2分）</p><ul><li>分页/分段、页面置换算法（FIFO、LRU）</li><li>段页式存储的地址转换（逻辑地址→物理地址）</li><li>页面置换算法的缺页率计算（FIFO 的 Belady 异常）</li><li>虚拟内存的核心原理（局部性原理）</li></ul></li><li><p><strong>磁盘调度</strong>（1分）</p><ul><li>SCAN（电梯算法）、C-SCAN</li><li>其他调度算法：FCFS、SSTF（最短寻道时间优先）</li><li>调度算法的寻道长度计算（必考）</li></ul></li><li><p><strong>文件系统</strong></p><ul><li>索引文件、链式文件、顺序文件的优缺点</li><li>作业调度：先来先服务、短作业优先、高响应比优先（计算作业周转时间、带权周转时间）</li></ul></li></ol><hr><h2 id="五、数据库系统-6分-【中优先级】" tabindex="-1">五、数据库系统（6分）【中优先级】 <a class="header-anchor" href="#五、数据库系统-6分-【中优先级】" aria-label="Permalink to &quot;五、数据库系统（6分）【中优先级】&quot;">​</a></h2><h3 id="高频考点-3" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-3" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>规范化理论</strong>（必考，2-3分）</p><ul><li>1NF/2NF/3NF/BCNF判断</li><li>函数依赖、部分依赖、传递依赖</li><li>候选键的求解方法（属性闭包计算，必考）</li><li>模式分解的原则（无损连接、保持函数依赖）</li><li>4NF（多值依赖，近年偶考）</li></ul></li><li><p><strong>关系代数</strong>（必考，2分）</p><ul><li>选择(σ)、投影(π)、连接(⋈)、自然连接</li><li>除运算、笛卡尔积（易混考点）</li><li>外部连接（左外、右外、全外）的结果特征</li><li>关系代数与 SQL 语句的转换（如 SELECT 对应投影 + 选择）</li></ul></li><li><p><strong>E-R模型</strong>（1-2分）</p><ul><li>实体、属性、联系（1:1、1:n、m:n）</li><li>E-R图转关系模式</li><li>弱实体的表示与转换（需依赖强实体的主键）</li><li>多对多联系转关系模式时需新增关系表，包含双方主键</li></ul></li><li><p><strong>并发控制</strong>（1分）</p><ul><li>封锁协议、三级封锁协议</li><li>事务的 ACID 特性（原子性、一致性、隔离性、持久性）</li><li>并发问题：脏读、不可重复读、幻读（隔离级别对应解决策略）</li><li>锁的类型：共享锁（S）、排他锁（X）</li></ul></li><li><p><strong>数据库索引</strong></p><ul><li>聚簇索引、非聚簇索引的区别</li></ul></li></ol><hr><h2 id="六、计算机硬件基础-6分-【中优先级】" tabindex="-1">六、计算机硬件基础（6分）【中优先级】 <a class="header-anchor" href="#六、计算机硬件基础-6分-【中优先级】" aria-label="Permalink to &quot;六、计算机硬件基础（6分）【中优先级】&quot;">​</a></h2><h3 id="高频考点-4" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-4" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>流水线</strong>（必考，2分）</p><ul><li>流水线周期、吞吐率、加速比计算</li><li>流水线计算公式： <ul><li>总执行时间 =（n-1）× 周期 + 所有子过程时间和 。</li><li>吞吐率 = 任务数 / 总执行时间</li></ul></li></ul></li><li><p><strong>运算基础</strong>（2分）</p><ul><li>浮点数表示、溢出判断（双符号位法）</li><li>原码、反码、补码的计算（整数 / 小数）</li><li>CRC 校验、海明校验（校验位计算、检错纠错能力）</li><li>定点数加减运算（补码运算规则）</li></ul></li><li><p><strong>存储体系</strong>（1-2分）</p><ul><li>Cache映射方式、三级存储结构</li><li>Cache 映射：直接映射、全相联映射、组相联映射（优缺点）</li><li>主存容量计算（地址线位数→存储容量：2^ 地址线位数 × 数据线位数 / 8）</li></ul></li><li><p><strong>CISC与RISC</strong>（1分）</p><ul><li>复杂指令集vs精简指令集特点</li><li>RISC 核心特征：固定长度指令、Load/Store 架构、大量通用寄存器</li><li>CISC 核心特征：复杂指令集、指令长度可变、指令执行时间可变</li></ul></li></ol><hr><h2 id="七、程序设计语言-6分-【中优先级】" tabindex="-1">七、程序设计语言（6分）【中优先级】 <a class="header-anchor" href="#七、程序设计语言-6分-【中优先级】" aria-label="Permalink to &quot;七、程序设计语言（6分）【中优先级】&quot;">​</a></h2><h3 id="高频考点-5" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-5" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>文法分类</strong>（Chomsky）（必考，2分）</p><ul><li>0型→3型文法规则与对应自动机</li><li>文法与语言的对应关系（3 型→正规语言，2 型→上下文无关语言）</li></ul></li><li><p><strong>有限自动机与正规式</strong>（必考，2分）</p><ul><li>DFA/NFA互转、正规式转换</li><li>DFA 的确定性：每个状态对每个输入符号只有一个后继状态</li><li>正规式与有限自动机的等价转换方法（必考例题）</li></ul></li><li><p><strong>参数传递</strong>（1-2分）</p><ul><li>值传递、引用传递区别</li></ul></li><li><p><strong>程序控制结构</strong></p><ul><li>顺序、选择、循环（结构化程序设计）</li></ul></li><li><p><strong>解释器与编译器</strong></p><ul><li>编译过程（词法分析→语法分析→语义分析→中间代码生成→优化→目标代码生成）</li><li>解释与编译的区别（解释器：逐句解释，编译器：一次编译，目标代码：可执行文件）</li></ul></li></ol><hr><h2 id="八、计算机网络-5分-【中低优先级】" tabindex="-1">八、计算机网络（5分）【中低优先级】 <a class="header-anchor" href="#八、计算机网络-5分-【中低优先级】" aria-label="Permalink to &quot;八、计算机网络（5分）【中低优先级】&quot;">​</a></h2><h3 id="高频考点-6" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-6" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>OSI模型</strong>（必考，2分）</p><ul><li>七层结构、各层功能与协议</li><li>OSI 与 TCP/IP 模型的对应（TCP/IP 为 4 层：网络接口层、网际层、传输层、应用层）</li><li>各层核心协议： <ul><li>物理层：RJ45、光纤、调制解调</li><li>数据链路层：以太网、PPP、ARP/RARP</li><li>网络层：IP、ICMP、IGMP</li><li>传输层：TCP、UDP</li><li>应用层：HTTP、FTP、SMTP、DNS</li></ul></li></ul></li><li><p><strong>TCP/IP协议族</strong>（必考，2分）</p><ul><li>TCP三次握手、UDP特点</li><li>常用端口：HTTP(80)、HTTPS(443)、FTP(21)</li><li>TCP 四次挥手过程（原因：确保数据传输完成）</li><li>常用端口补充：SSH (22)、Telnet (23)、DNS (53)、SMTP (25)、POP3 (110)</li></ul></li><li><p><strong>子网划分</strong>（必考，2分）</p><ul><li>CIDR计算、网络地址/广播地址/可用IP范围</li><li>子网掩码的作用、无类路由（CIDR）的表示方法（如 192.168.1.0/24）</li><li>子网划分计算步骤：确定子网位数→子网数→每个子网可用 IP 数</li></ul></li><li><p><strong>网络拓扑</strong></p><ul><li>星型、总线型、环型、网状拓扑的优缺点</li></ul></li><li><p><strong>网络命令</strong></p><ul><li>ping（ICMP）、ipconfig/ifconfig、tracert、netstat（功能与应用）</li></ul></li></ol><hr><h2 id="九、信息安全知识-5分-【中低优先级】" tabindex="-1">九、信息安全知识（5分）【中低优先级】 <a class="header-anchor" href="#九、信息安全知识-5分-【中低优先级】" aria-label="Permalink to &quot;九、信息安全知识（5分）【中低优先级】&quot;">​</a></h2><h3 id="高频考点-7" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-7" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ol><li><p><strong>加密技术</strong>（必考，2-3分）</p><ul><li>对称加密：DES、AES</li><li>非对称加密：RSA</li><li>哈希函数：MD5、SHA-256</li><li>对称 vs 非对称加密的优缺点（对称快、密钥分发难；非对称慢、密钥管理易）</li><li>常用加密算法细节：DES（56 位密钥）、AES（128/192/256 位）、RSA（基于大数分解）</li></ul></li><li><p><strong>网络攻击</strong>（1-2分）</p><ul><li>主动攻击：DoS、DDoS、SQL注入</li><li>被动攻击：窃听、流量分析</li></ul></li><li><p><strong>数字签名</strong>（1分）</p><ul><li>私钥签名、公钥验证</li><li>数字签名的流程：原文→哈希→私钥签名→发送；接收方→公钥验证签名→哈希对比原文</li><li>数字证书（CA 签发）的作用（解决公钥信任问题）</li></ul></li></ol><hr><h2 id="十、专业英语-5分-【低优先级】" tabindex="-1">十、专业英语（5分）【低优先级】 <a class="header-anchor" href="#十、专业英语-5分-【低优先级】" aria-label="Permalink to &quot;十、专业英语（5分）【低优先级】&quot;">​</a></h2><h3 id="高频考点-8" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-8" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ul><li><strong>核心词汇</strong>（重复率高）： <ul><li>数据结构：array, stack, queue, tree, sort</li><li>数据库：database, query, transaction</li><li>网络：protocol, TCP/IP, server</li><li>软件工程：software, test, debug</li><li>硬件：pipeline, cache, CPU, memory, register</li><li>操作系统：process, thread, deadlock, schedule</li><li>面向对象：class, object, inherit, polymorphism, interface</li><li>安全：encrypt, decrypt, hash, signature, firewall</li><li>算法：algorithm, complexity, recursion, search</li></ul></li></ul><hr><h2 id="十一、知识产权与标准化-3分-【最低优先级】" tabindex="-1">十一、知识产权与标准化（3分）【最低优先级】 <a class="header-anchor" href="#十一、知识产权与标准化-3分-【最低优先级】" aria-label="Permalink to &quot;十一、知识产权与标准化（3分）【最低优先级】&quot;">​</a></h2><h3 id="高频考点-9" tabindex="-1">高频考点 <a class="header-anchor" href="#高频考点-9" aria-label="Permalink to &quot;高频考点&quot;">​</a></h3><ul><li><strong>著作权</strong>（1分）：保护期限（作者终生+50年）</li><li><strong>专利权</strong>（1分）：发明20年，实用新型10年</li><li><strong>标准代号</strong>（1分）：GB（国标）、SJ（电子行业）</li><li><strong>商标权</strong>：有效期 10 年，可续展（每次 10 年）</li><li><strong>侵权判定</strong>：软件侵权的认定（复制、修改、发行等行为）</li></ul><hr><h2 id="备考策略" tabindex="-1">备考策略 <a class="header-anchor" href="#备考策略" aria-label="Permalink to &quot;备考策略&quot;">​</a></h2><ol><li><strong>抓大放小</strong>：优先攻克软件工程、面向对象、数据结构三大模块（合计33分）</li><li><strong>真题为王</strong>：近5年真题至少做2遍，总结错题规律</li><li><strong>公式必背</strong>：流水线、子网划分、可靠性计算等公式</li><li><strong>记忆技巧</strong>：用思维导图梳理知识点框架，对比记忆易混概念</li></ol>',51)])])}const c=i(o,[["render",e]]);export{p as __pageData,c as default};
